const i=JSON.parse('{"workId":"xijing-zaji","chapter":{"id":"xijing-zaji_ch-2","workId":"xijing-zaji","order":2,"title":"第二","difficulty":4,"estimatedMinutes":10,"passageIds":["xijing-zaji_ch-2_p-1","xijing-zaji_ch-2_p-2","xijing-zaji_ch-2_p-3","xijing-zaji_ch-2_p-4","xijing-zaji_ch-2_p-5","xijing-zaji_ch-2_p-6","xijing-zaji_ch-2_p-7","xijing-zaji_ch-2_p-8","xijing-zaji_ch-2_p-9","xijing-zaji_ch-2_p-10","xijing-zaji_ch-2_p-11","xijing-zaji_ch-2_p-12","xijing-zaji_ch-2_p-13","xijing-zaji_ch-2_p-14","xijing-zaji_ch-2_p-15","xijing-zaji_ch-2_p-16","xijing-zaji_ch-2_p-17","xijing-zaji_ch-2_p-18","xijing-zaji_ch-2_p-19","xijing-zaji_ch-2_p-20","xijing-zaji_ch-2_p-21","xijing-zaji_ch-2_p-22","xijing-zaji_ch-2_p-23","xijing-zaji_ch-2_p-24","xijing-zaji_ch-2_p-25","xijing-zaji_ch-2_p-26","xijing-zaji_ch-2_p-27","xijing-zaji_ch-2_p-28","xijing-zaji_ch-2_p-29","xijing-zaji_ch-2_p-30","xijing-zaji_ch-2_p-31"],"tags":[]},"passages":[{"id":"xijing-zaji_ch-2_p-1","chapterId":"xijing-zaji_ch-2","order":1,"canonicalText":"元帝後宮既多，不得常見，乃使畫工圖形，案圖召幸之。諸宮人皆賂畫工，多者十萬，少者亦不減五萬。獨王嬙不肯，遂不得見。後匈奴求美人，上案圖以嬙賜之。及去，召見，貌為後宮第一，善應對，舉止閑雅。帝悔之，而名籍已定。帝乃窮案其事，畫工毛延壽、陳敞、劉白、龔寬皆棄巿。","sentenceIds":["xijing-zaji_ch-2_p-1_s-1","xijing-zaji_ch-2_p-1_s-2","xijing-zaji_ch-2_p-1_s-3","xijing-zaji_ch-2_p-1_s-4","xijing-zaji_ch-2_p-1_s-5","xijing-zaji_ch-2_p-1_s-6","xijing-zaji_ch-2_p-1_s-7"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢元帝宮中的後宮嬪妃宮女數量極其龐大，皇帝無法一一親自召見審視，於是命令宮廷畫師繪製宮女們的肖像畫冊，元帝按圖索驥翻閱畫像來決定召見寵幸哪一位。後宮諸位宮女為了能夠得到皇帝寵幸，紛紛私下向畫工行賄送禮，行賄多的高達十萬錢，少的也絕不少於五萬錢！唯獨絕代佳人王嬙（王昭君）自恃美貌絕倫、為人高潔剛直，堅決不肯行賄畫師，畫工於是故意將她畫得醜陋平庸，昭君因此長年深居冷宮無法得到皇帝召見！後來匈奴呼韓邪單於前來朝覲請求和親迎娶大漢美人，元帝按畫冊挑選，見王嬙畫像最為醜陋，便決定將王嬙賞賜給匈奴單於！到了昭君即將出發臨行辭別之際，元帝在朝堂上正式召見，只見王昭君美艷絕倫、光彩照人，容貌冠絕整個漢家後宮，而且言辭談吐得體大方、舉止高雅優美（貌為後宮第一，舉止閑雅）！漢元帝無比震驚懊悔痛心，然而出塞的和親名冊與外交文書早已正式簽署底定無法反悔！元帝憤怒之極，回宮後立刻下令徹底徹查此案嚴懲貪腐，畫工毛延壽、陳敞、劉白、龔寬等一眾受賄貪腐畫師，全部被押赴長安市曹斬首示眾（皆棄市）！","analysis":"【題解與昭君出塞畫工毛延壽索賄被斬】本段為中國文學史與歷史戲曲最著名之千古名篇——王昭君出塞、毛延壽索賄醜化自食惡果之歷史母體！\\\\n【詞義訓詁】「王嬙」：王昭君，名嬙，字昭君；「案圖召幸」：按畫冊選美；「貌為後宮第一」：昭君出塞驚艷漢帝；「棄巿」：古代將罪犯於街市當眾處死示眾。\\\\n【貪腐與歷史悲劇】毛延壽等宮廷畫師的腐敗弄權，不僅埋沒了絕世美人的青春，更改變了漢匈和親的歷史走向，成為千百年來批判官場貪腐與弄權的經典警示。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-2","chapterId":"xijing-zaji_ch-2","order":2,"canonicalText":"武帝欲殺乳母，乳母告急於東方朔，朔曰：「帝忍而愎，旁人言之，益死之速耳。汝臨去，但屢顧我，我當設奇救汝。」及臨刑，乳母屢顧朔，朔叱之曰：「癡婦！帝已長矣，豈復藉汝乳而活耶！」帝悽然憫之，遂赦其罪。","sentenceIds":["xijing-zaji_ch-2_p-2_s-1","xijing-zaji_ch-2_p-2_s-2","xijing-zaji_ch-2_p-2_s-3","xijing-zaji_ch-2_p-2_s-4","xijing-zaji_ch-2_p-2_s-5"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢武帝因乳母家人犯法而盛怒之下準備處死自己的親生乳母，乳母嚇得魂飛魄散連忙向智囊東方朔哭訴求救。東方朔冷靜地對她說：當今皇上生性果斷嚴苛而且極其執拗剛愎（忍而愎），如果旁人上前公開求情勸諫，只會激起皇上怒火讓你死得更快罷了！等你被衛士押解推出去臨刑受死之際，你什麼話都不要說，只要頻頻回頭深情回望我，我自有奇策神計來救你的性命！到了臨刑受死那一刻，乳母依計而行，被押走時一步三回頭滿眼淚水頻頻回望東方朔；東方朔當著漢武帝的面突然站起身厲聲呵斥乳母道：你這個癡傻老婦人！如今皇上早就已經長大成人君臨天下了，難道還需要依賴喫你的奶水才能活命嗎！漢武帝聽到這句看似嚴厲斥責、實則極致喚醒童年哺育深情的反諷之語，內心深處頓時湧起無限淒涼與感傷憐憫（悽然憫之），當場下旨赦免了乳母的死罪！","analysis":"【題解與東方朔反諷機智救武帝乳母】東方朔運用高級幽默與心理反諷（豈復藉汝乳而活耶），巧妙喚醒漢武帝潛意識中的童年母愛感恩，化解帝王雷霆之怒！\\\\n【詞義訓詁】「東方朔」：西漢著名智者、詼諧大師；「忍而愎」：忍，冷酷嚴苛；愎，剛愎自用；「屢顧」：頻頻回頭張望；「悽然憫之」：被真情徹底打動而生憐憫。\\\\n【進諫藝術之最高境界】面對性格強勢剛愎的最高統治者，生硬死諫只會激化矛盾。運用詼諧反諷繞過心理防禦機制，直擊其內心最柔軟的人性底色，方為大智。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-3","chapterId":"xijing-zaji_ch-2","order":3,"canonicalText":"五侯不相能，賓客不得來往。婁護豐辯，傳食五侯間，各得其懽心，競致奇膳。護乃合以為鯖，世稱五侯鯖。","sentenceIds":["xijing-zaji_ch-2_p-3_s-1","xijing-zaji_ch-2_p-3_s-2","xijing-zaji_ch-2_p-3_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"《西京雜記·卷二》第三節講述：君子嚴於律己、不斷自我提升，小人則苛求他人。從個人的自我修養開始，齊整家族，進而治理國家並平定天下，這種偉大道德與制度將永載史冊，成為後世的典範。","analysis":"【主題與背景】\\\\\\\\n本段出自《西京雜記》卷二結尾，強調西漢文人墨客與朝臣在參與國家大一統建設時的自我道德期許與文明責任感。\\\\\\\\n【詞義與名物】\\\\\\\\n求諸己：反求諸己，自我約束與激勵。\\\\\\\\n修身齊家治國平天下：個體修養到天下和平的社會實踐。\\\\\\\\n憲章：永久遵循的典範規範。\\\\\\\\n【篇章解析】\\\\\\\\n本節結尾將卷二所呈現的西漢物質文明（宮苑文物）升華至精神文明層面，認為唯有具備「求諸己」的道德自覺與修齊治平的天下擔當，繁華的文明成果才能永垂憲章。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-4","chapterId":"xijing-zaji_ch-2","order":4,"canonicalText":"公孫弘起家徒步，為丞相，故人高賀從之。弘食以脫粟飯，覆以布被。賀怨曰：「何用故人富貴為？脫粟布被，與貧賤何異！」弘自若，以俸祿皆散給故人貧乏者。","sentenceIds":["xijing-zaji_ch-2_p-4_s-1","xijing-zaji_ch-2_p-4_s-2","xijing-zaji_ch-2_p-4_s-3","xijing-zaji_ch-2_p-4_s-4","xijing-zaji_ch-2_p-4_s-5"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"丞相公孫弘出身平民步卒赤貧階層（起家徒步），歷經奮鬥最終拜相封侯官至丞相，昔日的同鄉老朋友高賀前來投奔投靠他。公孫弘在家中用最粗糙的脫粟糙米飯招待高賀，睡覺時給他蓋粗布棉被。高賀內心極度怨恨憤憤不平地說：老朋友位極人臣大富大貴又有什麼用呢？天天讓我喫糙米飯、蓋破布被，這跟我老家的貧賤生活又有什麼兩樣！公孫弘神色自若絲毫不予計較，因為他把自己朝廷所發的巨額丞相俸祿，全部無私散發分給了老家各地的貧困孤寡鄉親！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 34 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「公孫弘起家徒步為丞相故人高賀從之弘食以脫粟飯……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「公」、「孫」、「弘」、「起」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-5","chapterId":"xijing-zaji_ch-2","order":5,"canonicalText":"文帝自代還，有良馬九匹，皆天下之駿馬也。一名浮雲，一名赤電，一名絕羣，一名逸驃，一名紫鷰騮，一名綠螭驄，一名龍子，一名嶙駒，一名絕塵，號為九逸。","sentenceIds":["xijing-zaji_ch-2_p-5_s-1","xijing-zaji_ch-2_p-5_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢文帝從代國返回長安繼位時，帶了九匹良馬，全都是天下罕見的駿馬。第一匹名叫浮雲，第二匹叫赤電，第三匹叫絕羣，第四匹叫逸驃，第五匹叫紫燕騮，第六匹叫綠螭驄，第七匹叫龍子，第八匹叫嶙駒，第九匹叫絕塵，當時的人將牠們合稱為九逸。","analysis":"【訓詁與名物】「文帝自代還」漢文帝劉恆原為代王，呂後死後被擁立為帝，自代地入長安。「逸驃」毛色黃白相間且奔跑極快的馬。「騮」讀ㄌㄧㄡˊ，黑鬃黑尾巴的紅馬。「紫鷰」形容馬的速度如紫燕般輕疾。「驄」讀ㄘㄨㄥ，青白相雜的馬。「綠螭」螭為傳說中無角的龍，形容馬的神駿。「嶙駒」骨骼奇特健壯的小馬。「絕塵」奔跑時腳不沾塵土，形容速度極快。「九逸」九匹絕世無雙的駿馬。\\\\n【章法與結構】本段是一則典型的「名物考證」式筆記。開頭先點明時間背景（文帝自代還）與核心物件（九匹天下駿馬）；接著採用平鋪直敘的列舉法，不厭其煩地將這九匹馬的名稱一一羅列出來；最後以一個總稱「號為九逸」作結。文章結構簡單，卻具有極強的目錄學與名物學價值。\\\\n【思想與義理】古代帝王往往將寶馬良駒視為國家強盛與天命所歸的象徵（如周穆王八駿）。這段記載將漢文帝即位時的九匹寶馬進行了詳細的命名紀錄。這些名字（如浮雲、赤電、絕塵）不僅極具文學美感與動態感，也反映了漢代人對於馬匹品種、毛色（如紫燕騮、綠螭驄）的精細分類與審美情趣。這為我們了解漢代發達的馬政文化與相馬術，提供了珍貴的歷史細節。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-6","chapterId":"xijing-zaji_ch-2","order":6,"canonicalText":"武帝時，身毒國獻連環羈，皆以白玉作之，馬瑙石為勒，白光琉璃為鞍。鞍在闇室中，常照十餘丈，如月光焉。","sentenceIds":["xijing-zaji_ch-2_p-6_s-1","xijing-zaji_ch-2_p-6_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢武帝的時候，身毒國（古印度）進獻了一套名為連環羈的馬具，全都是用純白的玉石製作而成的，並用瑪瑙石做成馬的轡頭（勒），用會發出白光的琉璃做成馬鞍。這個馬鞍如果放在黑暗的房間裡，能夠照亮周圍十幾丈的地方，就像月光一樣皎潔明亮。","analysis":"【訓詁與名物】「身毒國」讀ㄩㄢ ㄉㄨˊ（或ㄕㄣ ㄉㄨˊ），中國古代對印度的稱呼。「連環羈」用環環相扣的方式製成的馬絡頭。「馬瑙」即瑪瑙。「勒」帶有嚼子的馬絡頭。「琉璃」古代一種具有玻璃光澤的半透明工藝品或天然寶石。「闇室」黑暗的房間。「丈」長度單位，十餘丈形容光芒照射極遠。\\\\n【章法與結構】本段記載了一件充滿異國風情與神話色彩的貢品。文章前半段重點羅列了這套馬具各個部件所使用的奢華材質（白玉作羈、瑪瑙為勒、白光琉璃為鞍），展現了令人眩目的珠光寶氣；後半段則賦予這件物品一種超自然的物理特性（闇室常照十餘丈，如月光焉），極大滿足了讀者的奇幻想像。\\\\n【思想與義理】漢武帝時期，張騫通西域，打通了通往中亞與南亞（身毒）的貿易與朝貢路線。這段關於印度進獻發光馬具的記載，雖然帶有誇張的志怪色彩（如會像月亮般發光的琉璃馬鞍），但它真實反映了當時中原社會對於西方異國珍寶的強烈好奇與崇拜。同時，將如此昂貴的寶石（白玉、瑪瑙、琉璃）僅僅用來裝飾馬匹，也再次折射出大漢帝國在國力鼎盛時期的極度奢靡與對異域奇觀的佔有欲。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-7","chapterId":"xijing-zaji_ch-2","order":7,"canonicalText":"昭帝時，茂陵家人獻寶劍，上銘曰：直千金，壽萬歲。上藏之於武庫，為國之鎮寶。","sentenceIds":["xijing-zaji_ch-2_p-7_s-1","xijing-zaji_ch-2_p-7_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢昭帝在位之際，茂陵的一位農家百姓向朝廷進獻了一柄出土的傳世寶劍，劍身上鐫刻著古老金文銘文道：價值直抵千金，祝願國祚天壽萬歲！漢昭帝極其珍重地將這柄神劍珍藏在國家最高武庫之中，奉為保佑社稷江山的國家鎮國重寶！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 37 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「昭帝時茂陵家人獻寶劍上銘曰直千金壽萬歲上藏之……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「昭」、「帝」、「時」、「茂」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-8","chapterId":"xijing-zaji_ch-2","order":8,"canonicalText":"司馬相如初與卓文君還成都，居貧愁懣，以所著鷫鷞裘就巿人陽昌貰酒，與文君為懽。既而文君抱頸而泣曰：「我非不能富，何至窮悴如此！」相如乃與文君俱之臨邛，盡賣車騎，買一酒舍酤酒，文君當壚，相如滌器。","sentenceIds":["xijing-zaji_ch-2_p-8_s-1","xijing-zaji_ch-2_p-8_s-2","xijing-zaji_ch-2_p-8_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"才子司馬相如當初與才女卓文君私奔返回成都老家，家徒四壁極度貧困愁悶；相如毅然脫下身上唯一一件珍貴的鷫鷞鳥皮裘，拿到長安市場商人陽昌處典當賒換美酒（貰酒），與卓文君借酒澆愁共度歡樂時光。喝完酒後，卓文君動情地抱著相如的脖頸痛哭流涕道：我們卓家並非沒有百萬家產，何至於讓我們夫妻二人困窘窮苦到如此地步啊！司馬相如於是與文君毅然一同前往臨邛縣，變賣了身邊全部的車馬僕從，買下一間街邊小酒館開門賣酒；卓文君親自站在酒臺前掌勺賣酒（文君當壚），司馬相如則穿著粗布犢鼻褌親自在街市水槽邊洗刷酒器碗碟（相如滌器）！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 38 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「司馬相如初與卓文君還成都居貧愁懣以所著鷫鷞裘……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「司」、「馬」、「相」、「如」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-9","chapterId":"xijing-zaji_ch-2","order":9,"canonicalText":"慶安世年十五，為成帝侍郎。善鼓琴，能為《雙鳳離鸞》之曲。趙後悅之，白上，得出入御內，絕見愛幸。","sentenceIds":["xijing-zaji_ch-2_p-9_s-1","xijing-zaji_ch-2_p-9_s-2","xijing-zaji_ch-2_p-9_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"美少年慶安世年僅十五歲，便出任漢成帝的宮廷侍郎。他極其精通彈奏古琴，能夠創作並演奏神妙絕倫的《雙鳳離鸞》名曲。趙飛燕皇后聽聞後極其喜愛欣賞他，特意向漢成帝稟報請求，使慶安世獲得了可以自由出入皇帝後宮禁苑的特權，受到趙後與宮廷極其深厚的寵信愛重！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 39 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「慶安世年十五為成帝侍郎善鼓琴能為雙鳳離鸞……」之章法語感與對偶語氣。\\\\n2. 訓詁與古漢語範式：本段重點解讀「慶」、「安」、「世」等字詞之古代漢語語意、通假字與名物制度考釋。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：xijing-zaji_ch-2_p-9）。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-10","chapterId":"xijing-zaji_ch-2","order":10,"canonicalText":"太上皇徙長安，居深宮，悽愴不樂。高祖竊因左右問其故，以平生所好，皆屠販少年，酤酒賣餅，鬭鷄蹴踘，以此為歡，今皆無此，故不樂。高祖乃作新豐，徙諸故人實之，太上皇乃悅。","sentenceIds":["xijing-zaji_ch-2_p-10_s-1","xijing-zaji_ch-2_p-10_s-2","xijing-zaji_ch-2_p-10_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"太上皇劉太公跟隨漢高祖遷居長安之後，長年居住在未央宮深宮大院之中，整日鬱鬱寡歡、神色淒愴極度不快樂。漢高祖暗中通過身邊侍從詢問父親不快樂的原因，太上皇感慨地說：自己一生平生最熱愛的生活，是跟沛縣老家的殺豬小販、市井少年們在一起，喝酒喫餅、鬥雞踢球（鬭雞蹴踘），以此為人生最大樂趣；如今深宮之中全無這些人間煙火市井樂趣，所以內心極度苦悶！漢高祖聽聞後至純至孝，立刻在長安驪山腳下仿照沛縣老家街道格局營建了一座新豐城，把沛縣的故舊鄉親全體遷移進來居住；太上皇走進新豐城看見街市鬥雞賣餅如故，這才心花怒放歡喜快樂！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 40 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「太上皇徙長安居深宮悽愴不樂高祖竊因左右問其故……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「太」、「上」、「皇」、「徙」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-11","chapterId":"xijing-zaji_ch-2","order":11,"canonicalText":"漢諸陵寢，皆以竹為簾，簾皆為水紋及龍鳳之像。昭陽殿織珠為簾，風至則鳴，如珩珮之聲。","sentenceIds":["xijing-zaji_ch-2_p-11_s-1","xijing-zaji_ch-2_p-11_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"大漢各大帝王陵園的寢殿之中，全部採用精細竹絲編織成竹簾，竹簾上精巧編織出流暢的水波紋與神聖的龍鳳圖案。而趙昭儀居住的昭陽殿之中，更是用無數顆晶瑩珍珠串織成珠簾；微風吹拂之際珍珠互相撞擊發出清脆悅耳的鳴響，如同佩戴在身上的珩珮玉玉佩碰撞發出的仙樂天籟之聲！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 41 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「漢諸陵寢皆以竹為簾簾皆為水紋及龍鳳之像昭陽殿……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「漢」、「諸」、「陵」、「寢」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-12","chapterId":"xijing-zaji_ch-2","order":12,"canonicalText":"揚雄讀書，有人語之曰：「無為自苦，玄故難傳。」忽然不見。雄著《太玄經》，夢吐鳳凰，集《玄》書之上，雄乃續成之。","sentenceIds":["xijing-zaji_ch-2_p-12_s-1","xijing-zaji_ch-2_p-12_s-2","xijing-zaji_ch-2_p-12_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"西漢大學者揚雄在苦讀鑽研的時候，曾遇到一個神祕的人對他說：不要再這樣折磨自己了，《太玄經》這種深奧的學問本來就很難流傳後世的。說完那個人就忽然消失不見了。後來揚雄在撰寫《太玄經》的過程中，夢見自己口中吐出了一隻鳳凰，並停留在《太玄經》的書稿上，揚雄因此受到極大的鼓舞，最終繼續完成了這部著作。","analysis":"【訓詁與名物】「揚雄」西漢後期的哲學家、文學家、語言學家。「無為自苦」不要這樣自我折磨（指寫作太過艱辛）。「玄」指揚雄正在撰寫的哲學名著《太玄經》，該書模仿《易經》的體例，文辭極其深奧難懂。「傳」流傳。「吐鳳凰」古代傳說中代表文采華國、才華橫溢的祥瑞之兆。\\\\n【章法與結構】本段由兩個帶有神異色彩的短篇故事組成。前一個故事描寫了揚雄寫作時遇到的「神祕勸退者（忽然不見）」，點出了《太玄經》曲高和寡、艱澀難懂的宿命；後一個故事則是一場華麗的「夢境（夢吐鳳凰）」，象徵著揚雄才華的爆發與著作的偉大價值。兩者在悲觀與榮耀之間形成了強烈的戲劇張力。\\\\n【思想與義理】揚雄的《太玄經》因為過於深奧，在當時曾被譏笑為無用之書，但他本人卻堅信其價值。這段帶有筆記小說性質的記載，生動地反映了中國古代知識分子在面對「學術寂寞」時的矛盾心理：一方面他們深知自己的心血可能無人能懂（玄故難傳），承受著巨大的精神痛苦；另一方面，他們又需要透過某種近乎神啟的心理暗示（如夢吐鳳凰的祥瑞），來自我賦予學術創作的神聖性與歷史使命感，從而支撐自己完成艱難的著述。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-13","chapterId":"xijing-zaji_ch-2","order":13,"canonicalText":"司馬相如為《上林》、《子虛》賦，意思蕭散，不復與外事相關，控引天地，錯綜古今，忽然如睡，煥然如醒，賦成，遂大名於天下。","sentenceIds":["xijing-zaji_ch-2_p-13_s-1"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"司馬相如在構思創作名篇《子虛賦》與《上林賦》的過程之中，心靈意志達到了一種極度空靈超脫的蕭散境界，完全不再理會世俗外界的任何紛擾瑣事；他的筆觸宏闊包攬控引整座天地宇宙，縱橫交錯貫通古往今來所有歷史；創作時時而彷彿沉沉入睡魂遊天外，時而神采煥發如同醍醐灌頂豁然清醒！巨賦一經寫成，司馬相如的名聲頓時威震天下名垂千古！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 43 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「司馬相如為上林子虛賦意思蕭散不復與外事相關控……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「司」、「馬」、「相」、「如」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-14","chapterId":"xijing-zaji_ch-2","order":14,"canonicalText":"董仲舒夢蛟龍入懷，乃作《春秋繁露》詞。其思深旨遠，天人感應之學，由此大備。","sentenceIds":["xijing-zaji_ch-2_p-14_s-1","xijing-zaji_ch-2_p-14_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"大儒董仲舒在潛心鑽研《春秋》經義之時，夜裡夢見一條威嚴神聖的蛟龍飛入自己的懷抱之中，醒來後文思泉湧，於是創作了傳世名著《春秋繁露》的宏篇詞章！其思想深邃無比、立意宏遠廣博，漢代儒家以天人感應為核心的哲學體系，自此全面完備確立！","analysis":"【題解與董仲舒夢蛟龍入懷作春秋繁露】記載漢代新儒學宗師董仲舒創立「天人感應」與《春秋繁露》神聖經學體系之傳奇。\\\\n【詞義訓詁】「董仲舒」：西漢大儒，推動罷黜百家獨尊儒術；「春秋繁露」：董仲舒闡發春秋微言大義之哲學代表作；「蛟龍入懷」：象徵聖德與文思天啟。\\\\n【天人感應的儒學建構】董仲舒將儒家倫理與陰陽五行、災異譴告融為一體，構建了以「天人感應」為核心的漢代大一統國家意識形態。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-15","chapterId":"xijing-zaji_ch-2","order":15,"canonicalText":"或問揚雄為賦，雄曰：「讀千首賦，乃能為之。」夫積學深厚，辭章自工，非可強致也。","sentenceIds":["xijing-zaji_ch-2_p-15_s-1","xijing-zaji_ch-2_p-15_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"有人向揚雄請教如何才能寫好辭賦，揚雄回答說：必須先讀過一千首辭賦，然後才能夠自己動手寫。可見，只有累積了深厚扎實的學問基礎，寫出來的文章辭藻自然就會精巧工整，這絕對不是可以靠勉強湊合或速成所能達到的。","analysis":"【訓詁與名物】「或」有人。「揚雄」西漢著名辭賦家，與司馬相如並稱「揚馬」。「為賦」創作辭賦。「工」精巧、工整、優美。「強致」勉強達到、強求速成。\\\\n【章法與結構】本段為一則簡短的文學理論筆記。前半段以「問答對話」的形式，直接引述揚雄關於寫作經驗的名言（讀千首賦，乃能為之）；後半段則是作者（或記錄者）對這句話的歸納與評論（夫積學深厚...非可強致也），點破了量變產生質變的文學規律。\\\\n【思想與義理】這段話是中國古典文學理論中探討「繼承與創作（讀與寫）」關係的最著名論述之一。漢賦以辭藻華麗、用字艱深、鋪陳誇張著稱，對作者的詞彙量與學識要求極高。揚雄作為漢賦大家，他一針見血地指出：任何文學的創新與精巧（辭章自工），都必須建立在極其龐大的閱讀量與前人經驗的吸收之上（讀千首賦）。它打破了「文學純靠天才與靈感」的迷思，強調了「積學深厚」才是文學創作無法投機取巧的唯一正道（非可強致）。這對後世文學教育產生了深遠的影響。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-16","chapterId":"xijing-zaji_ch-2","order":16,"canonicalText":"匡衡字稚圭，勤學而無燭。鄰舍有燭而不逮，衡乃穿壁引其光，以書映光而讀之。邑人大姓文不識，家富多書，衡乃與其傭作而不求償。主人怪問衡，衡曰：「願得讀主人書。」主人感嘆，資給以書，遂成大儒。","sentenceIds":["xijing-zaji_ch-2_p-16_s-1","xijing-zaji_ch-2_p-16_s-2","xijing-zaji_ch-2_p-16_s-3","xijing-zaji_ch-2_p-16_s-4","xijing-zaji_ch-2_p-16_s-5"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"西漢名臣匡衡字稚圭，年輕求學時家境赤貧極度勤奮好學，然而家中夜晚貧困買不起蠟燭點燈。隔壁鄰居家每晚點著蠟燭但光線照不到匡衡家，匡衡於是在兩家的牆壁上悄悄鑿穿了一個小孔，引導隔壁透過來的一線微光，把書本映照在微光之下通宵達旦苦讀（鑿壁偷光）！同縣有一位藏書極其豐富的富豪名叫文不識，匡衡便主動前往文家給他當長工做繁重的苦力勞役，卻堅決分文不取工錢報酬。主人深感奇怪驚異地詢問匡衡原因，匡衡誠懇地說道：我只希望能有機會讀遍主人家中所收藏的全部書籍！主人聽後大受感動讚嘆不已，慷慨把家中的全部藏書免費借給他閱讀資助他求學，匡衡最終刻苦攻讀成為一代名震天下的大儒！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 46 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「匡衡字稚圭勤學而無燭鄰舍有燭而不逮衡乃穿壁引……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「匡」、「衡」、「字」、「稚」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-17","chapterId":"xijing-zaji_ch-2","order":17,"canonicalText":"長安有儒生曰惠莊，聞朱雲折五鹿充宗之角，乃嘆息曰：「栗犢反能爾邪！吾終恥溺死溝中。」遂裹糧從師，精研《春秋》，亦為名儒。","sentenceIds":["xijing-zaji_ch-2_p-17_s-1","xijing-zaji_ch-2_p-17_s-2","xijing-zaji_ch-2_p-17_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"長安城有一位儒生名叫惠莊，在聽聞太學生朱雲在朝堂經學辯論中以雄辯大才一舉駁倒大儒五鹿充宗（折五鹿充宗之角）之後，深受巨大震撼感嘆道：連朱雲這個平日像農村牛犢一樣粗魯剛烈的人（栗犢），尚且能夠在經學論辯中建此奇功！我如果庸庸碌碌一生、最終如同淹死在陰溝中一樣毫無作為，那將是我一生的莫大恥辱！於是惠莊立刻收拾行囊包裹乾糧出門尋訪名師，廢寢忘食精研《春秋》經義，最終也苦學成為一代名震海內的名儒！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 47 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「長安有儒生曰惠莊聞朱雲折五鹿充宗之角乃嘆息曰……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「長」、「安」、「有」、「儒」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-18","chapterId":"xijing-zaji_ch-2","order":18,"canonicalText":"武帝過李夫人，就取玉簪搔頭。自此後，宮人搔頭皆用玉，玉價倍貴焉。","sentenceIds":["xijing-zaji_ch-2_p-18_s-1","xijing-zaji_ch-2_p-18_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢武帝前往李夫人宮中探望探視，隨手順勢取下李夫人頭上佩戴的白玉髮簪用來搔頭止癢。從此之後，宮廷中的各位嬪妃宮女紛紛爭相效仿，日常搔頭固定髮髻全部改用玉簪（搔頭皆用玉），長安市場上的玉石價格因此暴漲數倍翻倍昂貴！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 48 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「武帝過李夫人就取玉簪搔頭自此後宮人搔頭皆用玉……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「武」、「帝」、「過」、「李」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-19","chapterId":"xijing-zaji_ch-2","order":19,"canonicalText":"杜陵杜夫子善弈棊，為天下第一人。或譏其費日，夫子曰：「精其理者，足以大裨聖教。」蓋圍棊之道，通於兵法政理也。","sentenceIds":["xijing-zaji_ch-2_p-19_s-1","xijing-zaji_ch-2_p-19_s-2","xijing-zaji_ch-2_p-19_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"長安杜陵的大師杜夫子極其擅長下圍棋（善弈棊），被公認為天下第一棋聖高手。當時有人譏諷批評他下棋是在白白浪費光陰耗費時日（費日），杜夫子從容回答說：能夠真正參透精通圍棋博弈之中陰陽攻守至理的人，其智慧完全足以極大裨益輔佐聖明先王的王道教化！因為圍棋的大道，本質上與軍事兵法調度和國家治理政治智慧是完全同一貫通的啊！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 49 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「杜陵杜夫子善弈棊為天下第一人或譏其費日夫子曰……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「杜」、「陵」、「杜」、「夫」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-20","chapterId":"xijing-zaji_ch-2","order":20,"canonicalText":"成帝好蹴踘，群臣以蹴踘為勞體，非至尊所宜。帝曰：「朕好之，可擇似而不勞者奏之。」家君作彈棊以獻，帝大悅，賜金百斤。","sentenceIds":["xijing-zaji_ch-2_p-20_s-1","xijing-zaji_ch-2_p-20_s-2","xijing-zaji_ch-2_p-20_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢成帝非常喜歡踢足球（蹴踘）。群臣認為踢足球太過消耗體力，不是尊貴的皇帝應該從事的運動，便加以勸諫。成帝說：但我就是喜歡玩，你們可以挑選一種性質類似足球，但又不會太勞累的遊戲進獻上來。於是，我的父親發明瞭一種名為彈棊的室內遊戲進獻給皇帝。成帝玩了之後非常高興，賞賜了黃金一百斤。","analysis":"【訓詁與名物】「蹴踘」讀ㄘㄨˋ ㄐㄩˊ，中國古代的足球運動，最初用於軍事訓練。「勞體」過度消耗體力。「至尊」指皇帝。「似」指性質或玩法類似蹴踘，具有競技性。「家君」作者對自己父親的尊稱（此處指劉向或某位宮廷近臣）。「彈棊」古代的一種室內棋類遊戲，雙方用手指彈擊棋子以擊打對方的棋子，類似現代的彈珠或桌球。\\\\n【章法與結構】本段是一則關於古代遊戲發明史的趣味筆記。文章按照「起因─發展─結果」的敘事結構展開：起因是成帝好蹴踘而群臣反對；發展是成帝提出了一個折衷的需求（似而不勞者）；結果是作者的父親順應聖意，發明瞭「彈棊」並獲得重賞。情節生動，充滿了生活氣息。\\\\n【思想與義理】這段記載不僅記錄了中國古代體育與遊戲發展史上的一件趣事（彈棊的發明），也側面反映了西漢中後期宮廷生活的奢靡與政治生態。漢成帝作為一個不理朝政的昏君，對於娛樂遊戲表現出極大的熱情（重賞百金）。而朝臣們雖然敢於勸諫皇帝不要做「勞體」的劇烈運動，但骨子裡卻還是為了迎合皇帝的享樂需求，甚至專門發明瞭室內微縮版的競技遊戲（彈棊）。這種君臣之間在「娛樂」上的互動，折射出當時政治風氣的輕浮與墮落。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-21","chapterId":"xijing-zaji_ch-2","order":21,"canonicalText":"元封二年，大寒，雪深五尺，野鳥獸皆死，牛馬皆踡蹜如蝟，三輔人民凍死者十有二三。武帝下詔賑恤，發太倉粟以救之。","sentenceIds":["xijing-zaji_ch-2_p-21_s-1","xijing-zaji_ch-2_p-21_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢武帝元封二年冬季，關中遭遇罕見極端特大寒潮嚴寒，大雪積雪深達五尺之厚，荒野之中的飛鳥野獸全部被活活凍死，民間的耕牛戰馬皆凍得蜷縮縮成一團如同一隻隻刺蝟（踡蹜如蝟），長安三輔地區的百姓平民被凍死者高達十分之二三！漢武帝聞訊極度震驚悲痛，立刻下達罪己與賑濟詔書，全面打開國家皇家太倉糧庫開倉放糧發放救濟物資，全力搶救受災百姓！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 51 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「元封二年大寒雪深五尺野鳥獸皆死牛馬皆踡蹜如蝟……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「元」、「封」、「二」、「年」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-22","chapterId":"xijing-zaji_ch-2","order":22,"canonicalText":"武帝為七寶牀，雜寶桉，廁寶屏風，列寶帳，設於桂宮，時人謂之四寶宮。皆以夜光珠、珊瑚、琉璃為之。","sentenceIds":["xijing-zaji_ch-2_p-22_s-1","xijing-zaji_ch-2_p-22_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢武帝耗資無數打造了七寶牀、雜寶案、廁寶屏風與列寶帳，整套奢華陳列安放在未央宮桂宮之中，當時的京城世人將這座宮殿稱之為四寶宮。這四套寶物全部採用罕見的夜光珍珠、深海紅珊瑚與五彩琉璃純工打造成！","analysis":"【題解與漢武帝桂宮四寶宮七寶牀雜寶案】描寫漢武帝桂宮內部集七寶牀、雜寶案、廁寶屏風、列寶帳於一體之頂級宮廷陳設工藝。\\\\n【詞義訓詁】「桂宮」：漢代未央宮北側離宮；「四寶宮」：以七寶牀、雜寶案、廁寶屏風、列寶帳著稱之奢華寢殿；「夜光珠」：古代發光珍珠。\\\\n【漢武帝時代的宮廷物質文明】漢武帝開拓西域四夷後，外國珍寶大量湧入長安，推動了皇家宮殿建築與室內工藝陳設達到前未有的繁複高峯。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-23","chapterId":"xijing-zaji_ch-2","order":23,"canonicalText":"瓠子河決，有蛟龍從九子自決中逆上入河，噴沫流波數十里。武帝親臨決所，沈白馬玉璧以祭之，乃築宮其上，號曰宣房。","sentenceIds":["xijing-zaji_ch-2_p-23_s-1","xijing-zaji_ch-2_p-23_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"黃河在瓠子口發生特大決口決堤（瓠子河決），洪水滔天之際，相傳有一條巨大蛟龍率領著九條龍子從決口洪水中逆流而上游入黃河，噴吐浪沫激起數十里的滔天巨浪！漢武帝親臨瓠子決口第一線指揮抗洪搶險，親自沉入白馬與名貴玉璧向河神祭祀，隨後發動數萬軍民合龍堵口，在決口故道之上修建宮殿紀念，命名為宣房宮！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 53 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「瓠子河決有蛟龍從九子自決中逆上入河噴沫流波數……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「瓠」、「子」、「河」、「決」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-24","chapterId":"xijing-zaji_ch-2","order":24,"canonicalText":"文帝初，多雨，積霖至百日而止。京師米貴，斛至萬錢。文帝減膳節用，開倉賑給，天下乃安。","sentenceIds":["xijing-zaji_ch-2_p-24_s-1","xijing-zaji_ch-2_p-24_s-2","xijing-zaji_ch-2_p-24_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢文帝即位初年，關中氣候極度異常連綿陰雨不斷，連續暴雨積霖整整下了一百天方纔停止！京師長安糧食短缺物價暴漲，一斛米價格竟然暴漲至一萬錢之巨！漢文帝身先士卒主動削減自己的御膳伙食、厲行節約節制宮廷開支，下令全面打開國家糧倉平價出售與免費發放糧食賑濟萬民，天下人心與社會秩序這才重新安定下來！","analysis":"【題解與文帝初年百日連陰雨減膳賑民】記錄漢文帝應對百日連陰雨極端氣候引發米價暴漲時「減膳節用、開倉賑給」之仁政風範。\\\\n【詞義訓詁】「積霖」：連綿不斷的大雨淫雨；「斛至萬錢」：米價飛漲反映極端糧食危機；「減膳節用」：皇帝主動削減御膳伙食以示自省悔過。\\\\n【古代天災應對與民本政治】面對重大自然災害，最高統治者主動節制宮廷消費、開倉賑濟災民，成為後世王朝應對水旱災荒的標準政治典範。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-25","chapterId":"xijing-zaji_ch-2","order":25,"canonicalText":"王鳳以五月五日生，其父欲不舉，曰：「俗諺：『舉五日子，長及戶則自害，不則害其父母。』」其叔父曰：「昔孟嘗君亦五月五日生，卒相齊。何害之有！」乃舉之，後果大貴，為大將軍。","sentenceIds":["xijing-zaji_ch-2_p-25_s-1","xijing-zaji_ch-2_p-25_s-2","xijing-zaji_ch-2_p-25_s-3","xijing-zaji_ch-2_p-25_s-4"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"西漢權臣王鳳恰好在農曆五月初五端午之日出生，他的父親王禁迷信民間惡俗想要遺棄不撫養他（欲不舉），說道：民間俗諺流傳：撫養五月五日出生的孩子，長大長到與門戶一樣高之際要麼自殘自殺，要麼就會剋死危害自己的父母！王鳳的叔父果斷站出來勸阻道：當年戰國四公子之一的孟嘗君田文也是在五月五日出生的，長大後最終官拜齊國正卿相國光宗耀祖！哪裡會有什麼危害呢！於是父親纔打消念頭撫養了他，王鳳長大後果然位極人臣大富大貴，官拜漢成帝大將軍執掌天下大權！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 55 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「王鳳以五月五日生其父欲不舉曰俗諺舉五日子長及……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「王」、「鳳」、「五」、「月」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-26","chapterId":"xijing-zaji_ch-2","order":26,"canonicalText":"惠帝七年夏，雷震南山。大木數千株，皆火燃至末。其下數十畝地，草皆燋黃。其後百許日，家人就其處得化玉，大如指，色如碧，可以闢兵。","sentenceIds":["xijing-zaji_ch-2_p-26_s-1","xijing-zaji_ch-2_p-26_s-2","xijing-zaji_ch-2_p-26_s-3","xijing-zaji_ch-2_p-26_s-4"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢惠帝七年夏天，雷暴閃電猛烈轟擊終南山。數千株參天大樹全部被天火雷擊引燃一直燒到樹梢末梢！雷火波及的下方數十畝山林土地，野草灌木全部被燒焦枯黃。在這場大火過去一百多天之後，當地山民前往火燒現場採集搜索，竟然在灰燼之中發現了高溫雷擊淬煉而成的奇異化玉，大小如同手指一般，顏色呈現深邃清澈的碧綠色，相傳隨身佩戴可以躲避兵刃刀劍傷害（闢兵）！","analysis":"【題解與惠帝七年雷震南山大火得闢兵化玉】記錄漢代終南山森林大火與雷電高溫熔融礦物形成「闢兵化玉（雷公墨/天然玻璃石）」之自然現象。\\\\n【詞義訓詁】「雷震南山」：雷電引發之秦嶺森林大火；「化玉」：高溫雷擊淬煉形成之熔融礦物；「闢兵」：闢通避，古代避除兵刃傷害之迷信信仰。\\\\n【漢代自然觀察與辟邪風俗】漢人將奇特的雷擊熔融礦物視為具有神異防護力量的靈物，生動反映了當時人們對自然奧祕的探索與樸素崇拜。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-27","chapterId":"xijing-zaji_ch-2","order":27,"canonicalText":"高祖為泗水亭長，送徒驪山，將與故人訣去。徒卒贈高祖酒二壼，鹿肚、牛肝各一。高祖與樂從者飲酒於豐西澤中，夜斬白蛇，遂起義兵。","sentenceIds":["xijing-zaji_ch-2_p-27_s-1","xijing-zaji_ch-2_p-27_s-2","xijing-zaji_ch-2_p-27_s-3"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"漢高祖劉邦當年擔任泗水亭長的時候，負責押送服役的民夫前往驪山，由於途中逃亡者眾多，他決定放走所有人，並準備與老朋友們訣別離去。那些被放走的役夫們湊錢贈送給高祖兩壺酒，以及鹿肚、牛肝各一份。高祖帶著那些願意跟隨他的人，在豐邑西邊的沼澤地裡喝酒壯膽。到了夜晚，他趁著酒意拔劍斬殺了一條擋路的白蛇，於是便就此起兵反秦了。","analysis":"【訓詁與名物】「泗水亭長」秦代基層官吏，主管當地治安。「徒」被徵發去服勞役的人。「驪山」秦始皇修建陵墓的地方。「訣去」訣別、離去（準備逃亡）。「徒卒」此指被押送的役夫。「樂從者」願意跟隨劉邦一起逃亡或起事的人。「斬白蛇」《史記》記載的劉邦起義神話，稱劉邦斬殺的白蛇是白帝之子，而劉邦是赤帝之子。\\\\n【章法與結構】本段以極其簡練的筆法，重述了漢高祖劉邦起義前夕的傳奇經歷。前一句交代了事件的背景與危機（送徒驪山，將訣去）；中間插入了一個正史未載的、極具市井生活氣息的微小細節（徒卒贈酒肉）；最後兩句則迅速拉昇了歷史的維度，將「飲酒豐澤」與「夜斬白蛇」這一開國神話相連接，最終落在「遂起義兵」的宏大歷史轉折上。\\\\n【思想與義理】《西京雜記》對「高祖斬白蛇」這一正史中充滿神學色彩的開國神話，進行了非常「世俗化」與「人情味」的細節補充。正史強調的是「赤帝子斬白帝子」的天命所歸；而這段記載卻特意記錄了役夫們贈送「酒二壼，鹿肚、牛肝」這樣粗鄙卻充滿江湖義氣的底層食物。這種視角的轉換，不僅讓劉邦這個流氓皇帝的形象更加立體與接地氣，也暗示了劉邦之所以能夠得天下，除了所謂的神話背書外，更重要的是他那種能夠在底層社會中收攏人心、與兄弟們大口喝酒喫肉的草莽江湖領袖氣質。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-28","chapterId":"xijing-zaji_ch-2","order":28,"canonicalText":"梁孝王好營宮室苑囿之樂，作曜華之宮，築兔園。園中有百靈山，山有膚寸石、落猿巖、棲龍岫；又有雁池，池中有鶴洲、鳧渚。天下名士鄒陽、枚乘、司馬相如皆遊其間，極一時之盛。","sentenceIds":["xijing-zaji_ch-2_p-28_s-1","xijing-zaji_ch-2_p-28_s-2","xijing-zaji_ch-2_p-28_s-3","xijing-zaji_ch-2_p-28_s-4"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"梁孝王劉武生平熱衷於營造宮殿園林遊賞之樂，在封國大興土木修建了富麗堂皇的曜華宮，修築了名震天下的梁園（兔園）。兔園之中堆疊修築了著名的百靈山，山中有形狀奇巧的膚寸石、險峻陡峭的落猿巖、雲霧繚繞的棲龍岫；園中又開鑿了浩瀚的雁池，池中散佈著仙鶴棲息的鶴洲與野鴨嬉戲的鳧渚。全天下的第一流辭賦名士如鄒陽、枚乘、司馬相如等人，無不匯聚在梁園之中遊賞賦詩，極盡漢代文人雅集盛極一時之盛況！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 58 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「梁孝王好營宮室苑囿之樂作曜華之宮築兔園園中有……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「梁」、「孝」、「王」、「好」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-29","chapterId":"xijing-zaji_ch-2","order":29,"canonicalText":"魯恭王好鬭雞鴨及鵝鴈，養孔雀、鵁鶄，俸穀一年費二千石。又壞孔子舊宅以廣其宮，聞金石絲竹之聲，乃不敢壞。","sentenceIds":["xijing-zaji_ch-2_p-29_s-1","xijing-zaji_ch-2_p-29_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"魯恭王劉餘生平極度喜愛鬥雞、鬥鴨以及觀賞鵝雁等禽鳥，在王府中大肆飼養珍禽孔雀與青頭鵁鶄，僅僅每年飼養禽鳥所消耗的王府俸祿穀物就多達兩千石之巨！後來他為了擴建自己的王宮大殿，竟然野蠻下令強拆孔子的曲阜舊宅（壞孔子宅）；在拆遷工人剛剛砸毀牆壁之際，忽然從牆壁廢墟之中傳來了神聖威嚴的鐘磬琴瑟金石絲竹仙樂之聲，魯恭王嚇得心驚膽戰，這才慌忙下令停工不敢再繼續拆毀！","analysis":"【題解與背景】\\\\n本段選自《西京雜記》〈第二〉第 59 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「魯恭王好鬭雞鴨及鵝鴈養孔雀鵁鶄俸穀一年費二千……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「魯」、「恭」、「王」、「好」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《西京雜記》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-30","chapterId":"xijing-zaji_ch-2","order":30,"canonicalText":"會稽歲時獻竹簟供御，世號為流黃簟。簟色如黃金，而滑澤如冰，夏月寢之，清涼徹骨。","sentenceIds":["xijing-zaji_ch-2_p-30_s-1","xijing-zaji_ch-2_p-30_s-2"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"會稽郡每年按時節都會進獻一種精美的竹蓆供皇帝御用，世人稱之為流黃簟。這種竹蓆的顏色呈現出如黃金般的光澤，而且表面光滑得就像冰一樣。在炎熱的夏天睡在這種竹蓆上，會感到有一股清涼的感覺直透骨髓。","analysis":"【訓詁與名物】「會稽」漢代郡名，位於今浙江紹興一帶，盛產竹子。「歲時」每年按季節、時令。「供御」供給皇帝使用。「流黃簟」一種高級的竹蓆，因其色澤如流動的黃金而得名。「滑澤」光滑潤澤。「徹骨」透入骨髓，形容極度清涼。\\\\n【章法與結構】本段是一則典型的名產風物誌。首句交代了物品的產地（會稽）、身價（供御）與名稱（流黃簟）；第二句從視覺與觸覺兩個維度（色如黃金、滑澤如冰），極力描寫這種竹蓆精美的物理特徵；最後一句則點出其實用價值（夏月寢之，清涼徹骨），給人以極強的感官體驗。\\\\n【思想與義理】這段記載生動地展現了漢代江南地區（會稽）高超的竹編工藝水平，以及長安宮廷對地方名優特產的搜羅與享受。「流黃簟」這個充滿詩意與富貴氣息的名字，結合了「色如黃金」與「滑澤如冰」的感官描寫，將一件原本普通的夏日寢具，昇華為一件集實用性與審美性於一身的藝術珍品。這也從一個側面反映了西漢盛世時期，物資交流的繁榮以及統治階層在日常生活起居上追求極致精緻與奢華的時代風貌。","historicalContext":"","keywords":[]}},{"id":"xijing-zaji_ch-2_p-31","chapterId":"xijing-zaji_ch-2","order":31,"canonicalText":"朱買臣為會稽太守，懷章綬還至舍亭，而國人未知也。所知錢勃，見其暴露，乃勞之曰：「得無罷乎？」買臣引勃入亭，飲之酒，出章綬示之，勃大驚，馳走告郡中，郡中震動，皆郊迎拜伏。買臣之妻見之，慚恨自經。","sentenceIds":["xijing-zaji_ch-2_p-31_s-1","xijing-zaji_ch-2_p-31_s-2","xijing-zaji_ch-2_p-31_s-3","xijing-zaji_ch-2_p-31_s-4"],"sourceRefs":[{"label":"《西京雜記》—中國哲學書電子化計劃","edition":"四部叢刊景宋本","location":"https://ctext.org/xijing-zaji/zh","accessedAt":"2026-08-31"},{"label":"《西京雜記》—維基文庫","edition":"四庫全書本《西京雜記》","location":"https://zh.wikisource.org/zh-hant/西京雜記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"名士朱買臣被漢武帝破格任命為會稽郡太守，他身穿破舊衣服將象徵太守最高權力的金印紫綬悄悄藏在懷中（懷章綬）步行返回故鄉抵達舍亭驛站，而會稽全郡百姓官員尚且絲毫不知新太守已然微服抵達。朱買臣的老相識錢勃看見他風塵僕僕衣衫襤褸暴露在烈日下，便上前同情地慰問他說：老朋友這一路長途奔波，該不會累壞了吧？朱買臣親切引導錢勃走進驛亭，請他痛飲美酒，隨後從懷中掏出金印紫綬展示給錢勃看！錢勃定睛一看大驚失色魂飛魄散，立刻飛奔疾馳跑進郡城向官署官員大聲通報；會稽全城官民大為震動驚慌，全體官吏迅速奔赴城郊跪拜俯伏迎接新太守！當年嫌貧愛富拋棄朱買臣另嫁他人的前妻在人羣中目睹這一切，羞愧懊悔得無地自容，當天便自縊懸樑自盡身亡！","analysis":"【題解與朱買臣懷章綬還會稽前妻慚恨自經】本段為中國古代文人逆襲與戲曲故事最經典之傳奇母體——朱買臣「馬前潑水、衣錦還鄉、懷章綬歸會稽」之全本掌故！\\\\n【詞義訓詁】「朱買臣」：西漢著名窮儒，早年砍柴讀書，五十歲拜會稽太守；「懷章綬」：懷揣太守印信微服還鄉；「自經」：上吊自盡。\\\\n【世態炎涼之歷史寓言】生動刻畫了世俗社會對貧寒之士的白眼與對權力財富的盲從拜金，極具戲劇張力與深刻的社會批判價值。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"xijing-zaji_ch-2_p-1_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-1","order":1,"canonicalText":"元帝後宮既多，不得常見，乃使畫工圖形，案圖召幸之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-1_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-1","order":2,"canonicalText":"諸宮人皆賂畫工，多者十萬，少者亦不減五萬。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-1_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-1","order":3,"canonicalText":"獨王嬙不肯，遂不得見。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-1_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-1","order":4,"canonicalText":"後匈奴求美人，上案圖以嬙賜之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-1_s-5","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-1","order":5,"canonicalText":"及去，召見，貌為後宮第一，善應對，舉止閑雅。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-1_s-6","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-1","order":6,"canonicalText":"帝悔之，而名籍已定。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-1_s-7","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-1","order":7,"canonicalText":"帝乃窮案其事，畫工毛延壽、陳敞、劉白、龔寬皆棄巿。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-2_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-2","order":1,"canonicalText":"武帝欲殺乳母，乳母告急於東方朔，朔曰：「帝忍而愎，旁人言之，益死之速耳。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-2_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-2","order":2,"canonicalText":"汝臨去，但屢顧我，我當設奇救汝。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-2_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-2","order":3,"canonicalText":"」及臨刑，乳母屢顧朔，朔叱之曰：「癡婦！","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-2_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-2","order":4,"canonicalText":"帝已長矣，豈復藉汝乳而活耶！","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-2_s-5","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-2","order":5,"canonicalText":"」帝悽然憫之，遂赦其罪。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-3_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-3","order":1,"canonicalText":"五侯不相能，賓客不得來往。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-3_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-3","order":2,"canonicalText":"婁護豐辯，傳食五侯間，各得其懽心，競致奇膳。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-3_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-3","order":3,"canonicalText":"護乃合以為鯖，世稱五侯鯖。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-4_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-4","order":1,"canonicalText":"公孫弘起家徒步，為丞相，故人高賀從之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-4_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-4","order":2,"canonicalText":"弘食以脫粟飯，覆以布被。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-4_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-4","order":3,"canonicalText":"賀怨曰：「何用故人富貴為？","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-4_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-4","order":4,"canonicalText":"脫粟布被，與貧賤何異！","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-4_s-5","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-4","order":5,"canonicalText":"」弘自若，以俸祿皆散給故人貧乏者。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-5_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-5","order":1,"canonicalText":"文帝自代還，有良馬九匹，皆天下之駿馬也。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-5_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-5","order":2,"canonicalText":"一名浮雲，一名赤電，一名絕羣，一名逸驃，一名紫鷰騮，一名綠螭驄，一名龍子，一名嶙駒，一名絕塵，號為九逸。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-6_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-6","order":1,"canonicalText":"武帝時，身毒國獻連環羈，皆以白玉作之，馬瑙石為勒，白光琉璃為鞍。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-6_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-6","order":2,"canonicalText":"鞍在闇室中，常照十餘丈，如月光焉。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-7_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-7","order":1,"canonicalText":"昭帝時，茂陵家人獻寶劍，上銘曰：直千金，壽萬歲。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-7_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-7","order":2,"canonicalText":"上藏之於武庫，為國之鎮寶。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-8_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-8","order":1,"canonicalText":"司馬相如初與卓文君還成都，居貧愁懣，以所著鷫鷞裘就巿人陽昌貰酒，與文君為懽。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-8_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-8","order":2,"canonicalText":"既而文君抱頸而泣曰：「我非不能富，何至窮悴如此！","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-8_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-8","order":3,"canonicalText":"」相如乃與文君俱之臨邛，盡賣車騎，買一酒舍酤酒，文君當壚，相如滌器。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-9_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-9","order":1,"canonicalText":"慶安世年十五，為成帝侍郎。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-9_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-9","order":2,"canonicalText":"善鼓琴，能為《雙鳳離鸞》之曲。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-9_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-9","order":3,"canonicalText":"趙後悅之，白上，得出入御內，絕見愛幸。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-10_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-10","order":1,"canonicalText":"太上皇徙長安，居深宮，悽愴不樂。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-10_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-10","order":2,"canonicalText":"高祖竊因左右問其故，以平生所好，皆屠販少年，酤酒賣餅，鬭鷄蹴踘，以此為歡，今皆無此，故不樂。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-10_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-10","order":3,"canonicalText":"高祖乃作新豐，徙諸故人實之，太上皇乃悅。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-11_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-11","order":1,"canonicalText":"漢諸陵寢，皆以竹為簾，簾皆為水紋及龍鳳之像。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-11_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-11","order":2,"canonicalText":"昭陽殿織珠為簾，風至則鳴，如珩珮之聲。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-12_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-12","order":1,"canonicalText":"揚雄讀書，有人語之曰：「無為自苦，玄故難傳。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-12_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-12","order":2,"canonicalText":"」忽然不見。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-12_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-12","order":3,"canonicalText":"雄著《太玄經》，夢吐鳳凰，集《玄》書之上，雄乃續成之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-13_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-13","order":1,"canonicalText":"司馬相如為《上林》、《子虛》賦，意思蕭散，不復與外事相關，控引天地，錯綜古今，忽然如睡，煥然如醒，賦成，遂大名於天下。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-14_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-14","order":1,"canonicalText":"董仲舒夢蛟龍入懷，乃作《春秋繁露》詞。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-14_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-14","order":2,"canonicalText":"其思深旨遠，天人感應之學，由此大備。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-15_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-15","order":1,"canonicalText":"或問揚雄為賦，雄曰：「讀千首賦，乃能為之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-15_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-15","order":2,"canonicalText":"」夫積學深厚，辭章自工，非可強致也。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-16_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-16","order":1,"canonicalText":"匡衡字稚圭，勤學而無燭。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-16_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-16","order":2,"canonicalText":"鄰舍有燭而不逮，衡乃穿壁引其光，以書映光而讀之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-16_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-16","order":3,"canonicalText":"邑人大姓文不識，家富多書，衡乃與其傭作而不求償。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-16_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-16","order":4,"canonicalText":"主人怪問衡，衡曰：「願得讀主人書。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-16_s-5","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-16","order":5,"canonicalText":"」主人感嘆，資給以書，遂成大儒。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-17_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-17","order":1,"canonicalText":"長安有儒生曰惠莊，聞朱雲折五鹿充宗之角，乃嘆息曰：「栗犢反能爾邪！","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-17_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-17","order":2,"canonicalText":"吾終恥溺死溝中。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-17_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-17","order":3,"canonicalText":"」遂裹糧從師，精研《春秋》，亦為名儒。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-18_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-18","order":1,"canonicalText":"武帝過李夫人，就取玉簪搔頭。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-18_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-18","order":2,"canonicalText":"自此後，宮人搔頭皆用玉，玉價倍貴焉。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-19_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-19","order":1,"canonicalText":"杜陵杜夫子善弈棊，為天下第一人。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-19_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-19","order":2,"canonicalText":"或譏其費日，夫子曰：「精其理者，足以大裨聖教。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-19_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-19","order":3,"canonicalText":"」蓋圍棊之道，通於兵法政理也。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-20_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-20","order":1,"canonicalText":"成帝好蹴踘，群臣以蹴踘為勞體，非至尊所宜。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-20_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-20","order":2,"canonicalText":"帝曰：「朕好之，可擇似而不勞者奏之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-20_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-20","order":3,"canonicalText":"」家君作彈棊以獻，帝大悅，賜金百斤。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-21_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-21","order":1,"canonicalText":"元封二年，大寒，雪深五尺，野鳥獸皆死，牛馬皆踡蹜如蝟，三輔人民凍死者十有二三。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-21_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-21","order":2,"canonicalText":"武帝下詔賑恤，發太倉粟以救之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-22_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-22","order":1,"canonicalText":"武帝為七寶牀，雜寶桉，廁寶屏風，列寶帳，設於桂宮，時人謂之四寶宮。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-22_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-22","order":2,"canonicalText":"皆以夜光珠、珊瑚、琉璃為之。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-23_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-23","order":1,"canonicalText":"瓠子河決，有蛟龍從九子自決中逆上入河，噴沫流波數十里。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-23_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-23","order":2,"canonicalText":"武帝親臨決所，沈白馬玉璧以祭之，乃築宮其上，號曰宣房。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-24_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-24","order":1,"canonicalText":"文帝初，多雨，積霖至百日而止。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-24_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-24","order":2,"canonicalText":"京師米貴，斛至萬錢。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-24_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-24","order":3,"canonicalText":"文帝減膳節用，開倉賑給，天下乃安。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-25_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-25","order":1,"canonicalText":"王鳳以五月五日生，其父欲不舉，曰：「俗諺：『舉五日子，長及戶則自害，不則害其父母。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-25_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-25","order":2,"canonicalText":"』」其叔父曰：「昔孟嘗君亦五月五日生，卒相齊。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-25_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-25","order":3,"canonicalText":"何害之有！","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-25_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-25","order":4,"canonicalText":"」乃舉之，後果大貴，為大將軍。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-26_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-26","order":1,"canonicalText":"惠帝七年夏，雷震南山。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-26_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-26","order":2,"canonicalText":"大木數千株，皆火燃至末。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-26_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-26","order":3,"canonicalText":"其下數十畝地，草皆燋黃。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-26_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-26","order":4,"canonicalText":"其後百許日，家人就其處得化玉，大如指，色如碧，可以闢兵。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-27_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-27","order":1,"canonicalText":"高祖為泗水亭長，送徒驪山，將與故人訣去。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-27_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-27","order":2,"canonicalText":"徒卒贈高祖酒二壼，鹿肚、牛肝各一。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-27_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-27","order":3,"canonicalText":"高祖與樂從者飲酒於豐西澤中，夜斬白蛇，遂起義兵。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-28_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-28","order":1,"canonicalText":"梁孝王好營宮室苑囿之樂，作曜華之宮，築兔園。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-28_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-28","order":2,"canonicalText":"園中有百靈山，山有膚寸石、落猿巖、棲龍岫；","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-28_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-28","order":3,"canonicalText":"又有雁池，池中有鶴洲、鳧渚。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-28_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-28","order":4,"canonicalText":"天下名士鄒陽、枚乘、司馬相如皆遊其間，極一時之盛。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-29_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-29","order":1,"canonicalText":"魯恭王好鬭雞鴨及鵝鴈，養孔雀、鵁鶄，俸穀一年費二千石。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-29_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-29","order":2,"canonicalText":"又壞孔子舊宅以廣其宮，聞金石絲竹之聲，乃不敢壞。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-30_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-30","order":1,"canonicalText":"會稽歲時獻竹簟供御，世號為流黃簟。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-30_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-30","order":2,"canonicalText":"簟色如黃金，而滑澤如冰，夏月寢之，清涼徹骨。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-31_s-1","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-31","order":1,"canonicalText":"朱買臣為會稽太守，懷章綬還至舍亭，而國人未知也。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-31_s-2","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-31","order":2,"canonicalText":"所知錢勃，見其暴露，乃勞之曰：「得無罷乎？","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-31_s-3","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-31","order":3,"canonicalText":"」買臣引勃入亭，飲之酒，出章綬示之，勃大驚，馳走告郡中，郡中震動，皆郊迎拜伏。","chunks":[],"tags":[]},{"id":"xijing-zaji_ch-2_p-31_s-4","workId":"xijing-zaji","chapterId":"xijing-zaji_ch-2","passageId":"xijing-zaji_ch-2_p-31","order":4,"canonicalText":"買臣之妻見之，慚恨自經。","chunks":[],"tags":[]}]}');export{i as default};
